INSERT INTO hotels (hotel_id, name, city, district, geo_lat, geo_lng, star_rating, user_rating, user_rating_count, amenities_json, address_json, policies_json, description, capacity_estimate) VALUES
  ('ho32jfc22c', 'Ginza Business Stay', 'Tokyo', 'Chuo', 35.671, 139.765, 4, 8.5, 252, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"6-8 Ginza","city":"Tokyo","country":"JP","geo_lat":35.6710,"geo_lng":139.7650}', '{"distance_to_venue_km":5.2,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Full-service hotel near Higashi-ginza offering an staffed business lounge and breakfast; higher nightly rate is offset by dependable late reception and straightforward taxi access.', 63),
  ('ho4fhk5nke', 'Nihonbashi Business Stay', 'Tokyo', 'Chuo', 35.681, 139.774, 4, 8.2, 303, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"9-8 Nihonbashi","city":"Tokyo","country":"JP","geo_lat":35.6810,"geo_lng":139.7740}', '{"distance_to_venue_km":6.0,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Older but well-reviewed property near Nihonbashi; airport rail access is convenient, while the morning trip to Roppongi requires a transfer and crowded platform navigation.', 72),
  ('ho6fqbwvct', 'Ikebukuro Business Stay', 'Tokyo', 'Toshima', 35.7295, 139.7109, 3, 7.8, 286, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"8-8 Ikebukuro","city":"Tokyo","country":"JP","geo_lat":35.7295,"geo_lng":139.7109}', '{"distance_to_venue_km":10.5,"cancellation_default":"Mixed refundable and prepaid plans","commute_note":"requires metro transfer to Roppongi"}', 'Large station-area hotel with broad room inventory and 24-hour reception; the cross-city journey to Roppongi is long enough to create a last-train risk after evening networking.', 69),
  ('ho6ga35kmq', 'Tokyo Station Business Stay', 'Tokyo', 'Chiyoda', 35.6812, 139.7671, 4, 8.7, 405, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"15-8 Tokyo Station","city":"Tokyo","country":"JP","geo_lat":35.6812,"geo_lng":139.7671}', '{"distance_to_venue_km":6.4,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Premium station-adjacent hotel with early breakfast and staffed luggage storage; direct taxis are convenient, although weekday road congestion makes arrival time variable.', 90),
  ('ho6vjvbkwi', 'Shinjuku Business Stay', 'Tokyo', 'Shinjuku', 35.6896, 139.7006, 3, 8.0, 235, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"5-8 Shinjuku","city":"Tokyo","country":"JP","geo_lat":35.6896,"geo_lng":139.7006}', '{"distance_to_venue_km":6.8,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'High-volume business hotel on the east side of Shinjuku; room supply is usually good, but the evening journey to Roppongi is vulnerable to crowding and missed connections.', 60),
  ('hodrmuxmqx', 'Meguro Business Stay', 'Tokyo', 'Meguro', 35.633, 139.715, 3, 8.0, 371, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"13-8 Meguro","city":"Tokyo","country":"JP","geo_lat":35.6330,"geo_lng":139.7150}', '{"distance_to_venue_km":4.6,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Residential-area business hotel near Meguro with quiet rooms and a useful desk; taxis to Roppongi are quick off peak but can slow substantially after weekday 17:00.', 84),
  ('hof2pyyhmt', 'Hamamatsucho Business Stay', 'Tokyo', 'Minato', 35.655, 139.756, 3, 8.0, 320, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"10-8 Hamamatsucho","city":"Tokyo","country":"JP","geo_lat":35.6550,"geo_lng":139.7560}', '{"distance_to_venue_km":4.7,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Business hotel close to the monorail and Daimon subway; practical for Haneda but rooms face the rail corridor, and the Roppongi commute includes a short walk from the Oedo line.', 75),
  ('hoj4niz2cx', 'Kanda Business Stay', 'Tokyo', 'Chiyoda', 35.6917, 139.7709, 3, 7.9, 388, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"14-8 Kanda","city":"Tokyo","country":"JP","geo_lat":35.6917,"geo_lng":139.7709}', '{"distance_to_venue_km":7.2,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Compact hotel by Kanda Station with coin laundry and early coffee service; the price is moderate, though two rail legs are needed to reach the conference venue.', 87),
  ('honvvzumkj', 'Azabu Business Stay', 'Tokyo', 'Minato', 35.654, 139.732, 4, 8.6, 184, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"2-8 Azabu","city":"Tokyo","country":"JP","geo_lat":35.6540,"geo_lng":139.7320}', '{"distance_to_venue_km":1.1,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Small serviced hotel between Azabu-juban and Roppongi with in-room washer, late self check-in, and a steep final walk from the metro that may matter with luggage.', 51),
  ('hony2mazrx', 'Akasaka Business Stay', 'Tokyo', 'Minato', 35.672, 139.736, 4, 8.4, 167, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"1-8 Akasaka","city":"Tokyo","country":"JP","geo_lat":35.6720,"geo_lng":139.7360}', '{"distance_to_venue_km":0.9,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Quiet corporate hotel near Akasaka Station with a direct short taxi ride to Roppongi; weekday breakfast starts at 06:30, while the compact desk is suitable for laptop work.', 48),
  ('hoqefhqs5g', 'Ebisu Business Stay', 'Tokyo', 'Shibuya', 35.6467, 139.7101, 4, 8.3, 218, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"4-8 Ebisu","city":"Tokyo","country":"JP","geo_lat":35.6467,"geo_lng":139.7101}', '{"distance_to_venue_km":3.3,"cancellation_default":"Mixed refundable and prepaid plans","commute_note":"requires metro transfer to Roppongi"}', 'Modern property near Ebisu with reliable workspace and several late dining options; reaching the summit requires one Hibiya-line connection and roughly twenty-five minutes door to door.', 57),
  ('hotcrpss4a', 'Odaiba Business Stay', 'Tokyo', 'Koto', 35.625, 139.775, 4, 8.4, 354, '["wifi","breakfast","gym","laundry","business_center"]', '{"line1":"12-8 Odaiba","city":"Tokyo","country":"JP","geo_lat":35.6250,"geo_lng":139.7750}', '{"distance_to_venue_km":11.8,"cancellation_default":"Mixed refundable and prepaid plans","commute_note":"requires metro transfer to Roppongi"}', 'Waterfront hotel with large rooms and bay views; conference access depends on the Yurikamome plus subway, making it a poor choice when sessions end late.', 81),
  ('hotel_ariake_bay', 'Tokyo Bay Ariake Hotel', 'Tokyo', 'Koto', 35.638, 139.794, 4, 8.5, 210, '["wifi","breakfast","gym","pool"]', '{"line1":"3-1-1 Ariake","city":"Tokyo","country":"JP","geo_lat":35.6380,"geo_lng":139.7940}', '{"distance_to_venue_km":12.0,"cancellation_default":"Free cancellation until 18:00 day before"}', 'Large convention-area hotel with pool and spacious rooms; attractive amenities do not offset a roughly forty-minute multi-line commute to Roppongi.', 100),
  ('hotel_narita_transit', 'Narita Airport Transit Hotel', 'Narita', 'Chiba', 35.772, 140.3884, 3, 7.8, 95, '["wifi","airport_shuttle","breakfast"]', '{"line1":"1-1 Narita Airport","city":"Narita","country":"JP","geo_lat":35.7720,"geo_lng":140.3884}', '{"distance_to_venue_km":70,"cancellation_default":"Free cancellation until 18:00 same day","airport_shuttle":"free 24h"}', 'Terminal-area overnight option with a scheduled all-terminal shuttle, breakfast from 05:30, and same-day flexible rates suited to an early recovery flight rather than the summit commute.', 40),
  ('hotel_roppongi_biz', 'Roppongi Business Hotel', 'Tokyo', 'Roppongi', 35.6605, 139.7292, 4, 8.7, 320, '["wifi","breakfast","gym","laundry","restaurant"]', '{"line1":"7-2-8 Roppongi","city":"Tokyo","country":"JP","geo_lat":35.6605,"geo_lng":139.7292}', '{"distance_to_venue_km":0.5,"cancellation_default":"Free cancellation until 18:00 day before","conference_rate_available":true}', 'Four-star business property five minutes on foot from the conference center, with breakfast, laundry, a staffed desk, and both refundable and prepaid inventory.', 80),
  ('hotel_roppongi_capsule', 'Roppongi Capsule Inn', 'Tokyo', 'Roppongi', 35.662, 139.73, 2, 7.2, 150, '["wifi","shared_bath","locker"]', '{"line1":"3-15 Roppongi","city":"Tokyo","country":"JP","geo_lat":35.6620,"geo_lng":139.7300}', '{"distance_to_venue_km":0.7,"cancellation_default":"Non-refundable"}', 'Low-cost capsule accommodation near the venue with shared bathing and locker-only storage; every offered rate is prepaid and unsuitable for confidential calls.', 30),
  ('hotel_shinagawa_value', 'Shinagawa Value Stay', 'Tokyo', 'Shinagawa', 35.6285, 139.7386, 3, 8.2, 180, '["wifi","laundry","metro_nearby"]', '{"line1":"2-5-1 Konan","city":"Tokyo","country":"JP","geo_lat":35.6285,"geo_lng":139.7386}', '{"distance_to_venue_km":6.2,"cancellation_default":"Free cancellation until 12:00 day before","metro_last_train_risk":"moderate"}', 'Budget single rooms near Shinagawa Station with laundry and strong airport access; the summit commute is longer and late-night return options narrow after midnight.', 60),
  ('hou7v77wbx', 'Ueno Business Stay', 'Tokyo', 'Taito', 35.7138, 139.777, 3, 7.9, 269, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"7-8 Ueno","city":"Tokyo","country":"JP","geo_lat":35.7138,"geo_lng":139.7770}', '{"distance_to_venue_km":9.0,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Simple hotel near Ueno with airport-rail convenience and late check-in; the transfer to the Hibiya line adds walking and makes it less practical than central Minato options.', 66),
  ('howm6kb5pg', 'Asakusa Business Stay', 'Tokyo', 'Taito', 35.7148, 139.7967, 3, 8.1, 337, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"11-8 Asakusa","city":"Tokyo","country":"JP","geo_lat":35.7148,"geo_lng":139.7967}', '{"distance_to_venue_km":11.0,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Traditional east-Tokyo property near Asakusa Station; attractive weekend rate, but the two-transfer commute to Roppongi can exceed forty minutes during the morning peak.', 78),
  ('hoxofkcujx', 'Shibuya Business Stay', 'Tokyo', 'Shibuya', 35.6595, 139.7005, 3, 8.1, 201, '["wifi","laundry","front_desk","metro_nearby"]', '{"line1":"3-8 Shibuya","city":"Tokyo","country":"JP","geo_lat":35.6595,"geo_lng":139.7005}', '{"distance_to_venue_km":3.8,"cancellation_default":"Free cancellation until 18:00 day before","commute_note":"requires metro transfer to Roppongi"}', 'Busy station-side hotel with 24-hour reception and many dining choices; a direct bus is unreliable at peak times, while rail access to Roppongi remains manageable.', 54);
